const sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Fetch one package's meta from the mirror. The mirror answers 429
// intermittently, so back off and retry a limited package before
// giving up; anything else (404, missing file) is a real failure.
async function fetchMeta(name) {
  const attempts = 5;
  for (let tryN = 1; tryN <= attempts; tryN++) {
    try {
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      return { ok: true, meta };
    } catch (err) {
