        const backoffMs = 300 * tryN;
        console.error("WARN 429 Too Many Requests: " + name +
          " (registry mirror busy, retrying in " + backoffMs + "ms)");
        await sleep(backoffMs);
      }
    }
  }
  return { ok: false };
}

