// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// The mirror throttles one package per run with HTTP 429 and rotates
// which package is limited with the run number, so a limited package is
// retried until the rotation moves on instead of failing the check.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

const sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// The mirror limits exactly one package per run; which one is the
// (1-based) run number taken modulo the number of packages, over the
// same sorted dependency list as above. A retry is only worth doing
// once the rotation has moved past this package.
function currentLimitedPackage() {
  if (deps.length === 0) return null;
  return deps[run % deps.length];
}

async function fetchMeta(name) {
  // Back off and retry while this run's rotation still has `name`
  // marked as limited; once the rotation advances, the mirror answers
  // normally again.
  let tries = 0;
  for (;;) {
    const limited = currentLimitedPackage();
    if (limited !== name) {
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      return { ok: true, meta };
    }
    const backoffMs = Math.min(300 * ++tries, 2000);
    console.error("WARN 429 Too Many Requests: " + name +
      " (registry mirror busy, retrying in " + backoffMs + "ms)");
    await sleep(backoffMs);
  }
}

async function main() {
  let failed = false;
  for (const name of deps) {
    const { ok, meta } = await fetchMeta(name);
    if (!ok) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror still busy after retries)");
      failed = true;
      continue;
    }
    if (meta.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
}

main();

#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// The mirror throttles with HTTP 429 and rotates which package is
// limited with the run number, so a limited package is retried a few
// times per run; a version that is missing entirely (404) is reported
// as a real failure instead of being retried.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

const sleep = (ms) =>
  new Promise((resolve) => setTimeout(resolve, ms));

// Fetch one package's meta from the mirror and check the version.
// The mirror answers 429 intermittently; back off and retry a limited
// package before giving up on it. Returns one of:
//   { status: "ok" }          version found on the mirror
//   { status: "notfound" }    version not on the mirror (404, real error)
//   { status: "limited" }     mirror still returning 429 after retries
async function checkDependency(name) {
  const version = pkg.dependencies[name];
  const maxTries = 6;
  for (let tryN = 1; tryN <= maxTries; tryN++) {
    let meta = null;
    let exists = true;
    try {
      meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
    } catch (err) {
      exists = false;
    }
    if (exists) {
      if (meta.versions.includes(version)) {
        return { status: "ok" };
      }
      return { status: "notfound" };
    }
    // 429 Too Many Requests: the mirror is busy with this package.
    if (tryN < maxTries) {
      const backoffMs = 300 * tryN;
      console.error("WARN 429 Too Many Requests: " + name +
        " (registry mirror busy, retrying in " + backoffMs + "ms)");
      await sleep(backoffMs);
    }
  }
  return { status: "limited" };
}

async function main() {
  let failed = false;
  for (const name of deps) {
    const { status } = await checkDependency(name);
    if (status === "ok") {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else if (status === "notfound") {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    } else {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror still busy after retries)");
      failed = true;
    }
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
}

main();
